def verifier(assign):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return abs(a)

    try:
        c1 = assign['c1']
        c2 = assign['c2']
        a = assign['a']
        b = assign['b']
        P = assign['P']
    except KeyError:
        return False, "Missing one or more required parameters."

    if not all(isinstance(v, int) for v in [c1, c2, a, b, P]):
        return False, "All parameters must be integers."

    if a not in [2, 3]:
        return False, "Base 'a' must be 2 or 3."

    if b <= a or a <= 1:
        return False, "Invalid bases 'a' and 'b'."
    try:
        k_float = math.log(b, a)
        k = int(round(k_float))
        if abs(k - k_float) > 1e-9:
            return False, "'b' must be an integer power of 'a'."
    except (ValueError, OverflowError):
        return False, "Logarithm calculation failed for bases."

    if not (2 <= k <= 4):
        return False, f"Deduced power k={k} is out of the expected range [2, 4]."

    c1_max = 0
    if k == 2: c1_max = 6
    elif k == 3: c1_max = 4
    elif k == 4: c1_max = 3

    if not (2 <= c1 <= c1_max):
        return False, f"c1 is out of the valid range for k={k}."

    c1k = c1 * k
    if not (1 <= c2 < c1k):
        return False, "c2 is out of the valid range."

    if gcd(c1, c2) != 1:
        return False, "c1 and c2 must be coprime."

    if P != c1k - c2:
        return False, "P is not correctly computed as c1*k - c2."

    # All domain conditions for the logarithms are satisfied by the constraints above.
    # Specifically, log arguments are > 1 because c2 > 0 and P > 0.

    answer = k**c1k

    if answer > 100000:
        return False, "Answer is too large, indicating generator constraint failure."

    return True, answer


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
